var RUNE={'a':'ᚨ','b':'ᛒ','c':'ᚲ','d':'ᛞ','e':'ᛖ','f':'ᚠ','g':'ᚷ','h':'ᚺ','i':'ᛁ','j':'ᛃ','k':'ᚲ','l':'ᛚ','m':'ᛗ','n':'ᚾ','o':'ᛟ','p':'ᛈ','q':'ᚲ','r':'ᚱ','s':'ᛋ','t':'ᛏ','u':'ᚢ','v':'ᚠ','w':'ᚹ','x':'ᛉ','y':'ᛁ','z':'ᛉ'};
function toRunes(s){return s.toLowerCase().split('').map(function(c){return RUNE[c]!=null?RUNE[c]:c;}).join('');}
function fromRunes(s){var inv={};for(var k in RUNE)inv[RUNE[k]]=k;return s.split('').map(function(c){return inv[c]!=null?inv[c]:c;}).join('');}
var EXPORTS={toRunes:toRunes,fromRunes:fromRunes,RUNE:RUNE};


if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.RuneForgePure = EXPORTS; }
